}

export interface CoarMenuAimConfigProvider {
  getMenuAimConfig(): CoarMenuAimConfig;
}

export const DEFAULT_COAR_MENU_AIM_CONFIG: CoarMenuAimConfig = {
  enabled: true,
  debugEnabled: false,
  switchDelayMs: 500,
  sampleMaxAgeMs: 200,
};

